CREATE TABLE `User` (`id` VARCHAR(191) NOT NULL,`phone` VARCHAR(32) NOT NULL,`passwordHash` VARCHAR(255) NOT NULL,`displayName` VARCHAR(80) NOT NULL,`role` ENUM('PATIENT','DOCTOR','NUTRITIONIST','ADMIN') NOT NULL,`status` ENUM('ACTIVE','DISABLED') NOT NULL DEFAULT 'ACTIVE',`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `User_phone_key`(`phone`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CareRelation` (`id` VARCHAR(191) NOT NULL,`patientId` VARCHAR(191) NOT NULL,`practitionerId` VARCHAR(191) NOT NULL,`status` ENUM('PENDING','ACTIVE','ENDED') NOT NULL DEFAULT 'PENDING',`inviteCode` VARCHAR(40) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`endedAt` DATETIME(3) NULL,UNIQUE INDEX `CareRelation_inviteCode_key`(`inviteCode`),INDEX `CareRelation_practitionerId_status_idx`(`practitionerId`,`status`),UNIQUE INDEX `CareRelation_patientId_practitionerId_key`(`patientId`,`practitionerId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `HealthRecord` (`id` VARCHAR(191) NOT NULL,`patientId` VARCHAR(191) NOT NULL,`weightKg` DECIMAL(5,2) NOT NULL,`waistCm` DECIMAL(5,2) NULL,`bodyFatPct` DECIMAL(5,2) NULL,`measuredAt` DATETIME(3) NOT NULL,`source` VARCHAR(32) NOT NULL DEFAULT 'MANUAL',`note` VARCHAR(500) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `HealthRecord_patientId_measuredAt_idx`(`patientId`,`measuredAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PatientTask` (`id` VARCHAR(191) NOT NULL,`patientId` VARCHAR(191) NOT NULL,`assignedById` VARCHAR(191) NOT NULL,`title` VARCHAR(120) NOT NULL,`description` VARCHAR(500) NULL,`status` ENUM('PENDING','COMPLETED','CANCELLED') NOT NULL DEFAULT 'PENDING',`dueAt` DATETIME(3) NULL,`completedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `PatientTask_patientId_status_idx`(`patientId`,`status`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Message` (`id` VARCHAR(191) NOT NULL,`senderId` VARCHAR(191) NOT NULL,`receiverId` VARCHAR(191) NOT NULL,`content` TEXT NOT NULL,`readAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `Message_senderId_receiverId_createdAt_idx`(`senderId`,`receiverId`,`createdAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `RefreshToken` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`tokenHash` VARCHAR(255) NOT NULL,`expiresAt` DATETIME(3) NOT NULL,`revokedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `RefreshToken_userId_expiresAt_idx`(`userId`,`expiresAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Consent` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`version` VARCHAR(32) NOT NULL,`scope` VARCHAR(80) NOT NULL,`grantedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`revokedAt` DATETIME(3) NULL,INDEX `Consent_userId_scope_idx`(`userId`,`scope`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AuditLog` (`id` VARCHAR(191) NOT NULL,`actorId` VARCHAR(191) NULL,`action` VARCHAR(80) NOT NULL,`resourceType` VARCHAR(80) NOT NULL,`resourceId` VARCHAR(80) NULL,`ipAddress` VARCHAR(64) NULL,`metadata` JSON NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX `AuditLog_actorId_createdAt_idx`(`actorId`,`createdAt`),INDEX `AuditLog_resourceType_resourceId_idx`(`resourceType`,`resourceId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `CareRelation` ADD CONSTRAINT `CareRelation_patientId_fkey` FOREIGN KEY (`patientId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `CareRelation` ADD CONSTRAINT `CareRelation_practitionerId_fkey` FOREIGN KEY (`practitionerId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `HealthRecord` ADD CONSTRAINT `HealthRecord_patientId_fkey` FOREIGN KEY (`patientId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `PatientTask` ADD CONSTRAINT `PatientTask_patientId_fkey` FOREIGN KEY (`patientId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `PatientTask` ADD CONSTRAINT `PatientTask_assignedById_fkey` FOREIGN KEY (`assignedById`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Message` ADD CONSTRAINT `Message_senderId_fkey` FOREIGN KEY (`senderId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Message` ADD CONSTRAINT `Message_receiverId_fkey` FOREIGN KEY (`receiverId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `RefreshToken` ADD CONSTRAINT `RefreshToken_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Consent` ADD CONSTRAINT `Consent_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `AuditLog` ADD CONSTRAINT `AuditLog_actorId_fkey` FOREIGN KEY (`actorId`) REFERENCES `User`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
